/* Blackline CAD2D — selección para revisión, paleta Baños.
  Geometría vectorial trazada en el DXF original del usuario BLOQUES OLIMPIADAS(2).
  Los tamaños son nominales (normalización proporcional), NO medición precisa de fabricante.
  Los originales se preservan. LAYER 0 / blanco en el insertador CAD2D.
  No añade bloques a módulos 3D ni sustituye definiciones existentes. */
(function(){'use strict';
const LIB=window.CAD2D_ARQ_LIBRARY;
if(!LIB||!Array.isArray(LIB.library)||!LIB.Builder)return;
const seen=new Set(LIB.library.map(x=>x.id));let added=0;
const rows=[["ca_ba_lv029","Lavatorio con mueble · vista frontal","Sanitarios",0.75,1.25,""],["ca_ba_lv103","Lavatorio con mesada · vista lateral","Sanitarios",0.75,1.178,""],["ca_ba_lv036","Lavatorio de pie · vista frontal","Sanitarios",0.75,1.2663,""],["ca_ba_lv121","Lavatorio · planta","Sanitarios",1.5,0.8581,""],["ca_ba_wc031","Inodoro · vista lateral","Sanitarios",0.75,1.1038,""],["ca_ba_wc044","Inodoro con mochila · vista frontal","Sanitarios",0.75,1.5875,""],["ca_ba_wc045","Inodoro con mochila · vista lateral","Sanitarios",0.75,1.0611,""],["ca_ba_wc058","Inodoro · planta","Sanitarios",0.75,1.2885,""],["ca_ba_wc070","Inodoro con depósito · planta","Sanitarios",0.75,0.6659,""],["ca_ba_du15","Ducha esquinera · planta","Sanitarios",0.75,0.75,""],["ca_ba_va015","Vanitory con espejo · vista frontal","Sanitarios",0.75,1.2839,""],["ca_ba_va034","Vanitory con mueble · vista frontal","Sanitarios",0.75,1.4155,""],["ca_ba_bi05","Bidet · vista frontal","Sanitarios",0.75,0.9839,""],["ca_ba_bi07","Bidet · vista lateral","Sanitarios",0.75,0.6566,""],["ca_ba_uri10","Mingitorio · planta","Sanitarios",0.75,1.1956,""]];
for(const [source,name,cat,w,d,data] of rows){
 const id='olymp2-curated-'+source.replace(/[^a-z0-9]+/g,'-');
 if(seen.has(id))continue;
 const bytes=atob(data);if(bytes.length<16||bytes.length%8)continue;
 LIB.library.push({id,source,name,cat,w,d,pro:true,author:'BLOQUES OLIMPIADAS(2).dxf · original del usuario',
  originalDXF:true,nominalDimensions:true,qualityReview:'Primera selección — Baños',
  wMin:w,wMax:w,dMin:d,dMax:d,
  gen(b,W,D){for(let i=0;i<bytes.length;i+=8){
   const n=j=>bytes.charCodeAt(i+j)+(bytes.charCodeAt(i+j+1)<<8);
   b.line(n(0)/65535*W,n(2)/65535*D,n(4)/65535*W,n(6)/65535*D);
  }}
 });seen.add(id);added++;
}
window.CAD2D_OLYMPIADAS_BANOS=Object.freeze({count:added,source:'BLOQUES OLIMPIADAS(2).dxf',status:'review-palette-by-palette'});
})();
